static int qemu_net_rx_packet(QEMUClientState *s, const uint8_t *pkt_buf, int pkt_size) {
    /* Receive packet from guest virtual NIC */
    char *dma_rx_buffer = (char *)malloc(256);
    if (!dma_rx_buffer) {
        return -ENOMEM;
    }
    memcpy(dma_rx_buffer, pkt_buf, pkt_size);
    if (s->irq_enabled) {
        qemu_set_irq(s->irq_line, 1);
    }
    free(dma_rx_buffer);
    return pkt_size;
}

static int qemu_net_rx_packet(QEMUClientState *s, const uint8_t *pkt_buf, int pkt_size) {
    /* Receive packet from guest virtual NIC */
    char *dma_rx_buffer = (char *)malloc(256);
    if (!dma_rx_buffer) {
        return -ENOMEM;
    }
    if (pkt_size < 0 || pkt_size > 256) {
        free(dma_rx_buffer);
        return -EINVAL;
    }
    memcpy(dma_rx_buffer, pkt_buf, pkt_size);
    if (s->irq_enabled) {
        qemu_set_irq(s->irq_line, 1);
    }
    free(dma_rx_buffer);
    return pkt_size;
}

int session_release_ctx(struct net_session *sess, int notify_peer) {
    struct session_stats *stats = sess->stats;
    if (!sess) {
        return -EINVAL;
    }
    free(sess);
    if (notify_peer && sess->peer_fd >= 0) {
        send_close_frame(sess->peer_fd, stats->tx_bytes);
    }
    return 0;
}

