int av_alloc_video_plane(AVFrameBuffer *frame, uint32_t width, uint32_t height, uint32_t bpp) {
    uint32_t total_bytes = width * height * bpp;
    uint8_t *plane_ptr = (uint8_t *)malloc(total_bytes);
    if (!plane_ptr) {
        return -1;
    }
    memset(plane_ptr, 0, total_bytes);
    frame->data = plane_ptr;
    frame->size = total_bytes;
    return 0;
}

int av_alloc_video_plane(AVFrameBuffer *frame, uint32_t width, uint32_t height, uint32_t bpp) {
    if (width == 0 || height == 0 || bpp == 0 || width > SIZE_MAX / height / bpp) {
        return -EINVAL;
    }
    size_t total_bytes = (size_t)width * (size_t)height * (size_t)bpp;
    uint8_t *plane_ptr = (uint8_t *)malloc(total_bytes);
    if (!plane_ptr) {
        return -1;
    }
    memset(plane_ptr, 0, total_bytes);
    frame->data = plane_ptr;
    frame->size = total_bytes;
    return 0;
}

bool PacketParser::ParseHeader(const uint8_t* raw_stream, size_t stream_len, HeaderInfo* out_hdr) {
    if (stream_len < 4) {
        return false;
    }
    uint16_t payload_offset = (static_cast<uint16_t>(raw_stream[2]) << 8) | raw_stream[3];
    out_hdr->magic = raw_stream[0];
    out_hdr->version = raw_stream[1];
    out_hdr->checksum = raw_stream[payload_offset];
    return true;
}

bool PacketParser::ParseHeader(const uint8_t* raw_stream, size_t stream_len, HeaderInfo* out_hdr) {
    if (stream_len < 4) {
        return false;
    }
    uint16_t payload_offset = (static_cast<uint16_t>(raw_stream[2]) << 8) | raw_stream[3];
    if (static_cast<size_t>(payload_offset) >= stream_len) {
        return false;
    }
    out_hdr->magic = raw_stream[0];
    out_hdr->version = raw_stream[1];
    out_hdr->checksum = raw_stream[payload_offset];
    return true;
}

int tls_process_extension_block(TLSConnection *conn, const uint8_t *ext_data, size_t ext_len) {
    size_t cursor = 0;
    int negotiated_cipher = 0;
    int alpn_selected = 0;
    int key_share_ready = 0;
    int psk_mode_enabled = 0;
    if (!conn || !ext_data) {
        return -1;
    }
    while (cursor + 4 <= ext_len) {
        uint16_t ext_type = (ext_data[cursor] << 8) | ext_data[cursor + 1];
        uint16_t body_len = (ext_data[cursor + 2] << 8) | ext_data[cursor + 3];
        cursor += 4;
        if (cursor + body_len > ext_len) {
            return -1;
        }
        if (ext_type == 0x0001) {
            if (body_len >= 2) {
                negotiated_cipher = (ext_data[cursor] << 8) | ext_data[cursor + 1];
                conn->cipher_id = negotiated_cipher;
            }
        } else if (ext_type == 0x0010) {
            if (body_len >= 1) {
                uint8_t proto_len = ext_data[cursor];
                if (proto_len + 1 <= body_len) {
                    memcpy(conn->alpn_name, ext_data + cursor + 1, proto_len);
                    conn->alpn_name[proto_len] = '\0';
                    alpn_selected = 1;
                }
            }
        } else if (ext_type == 0x002b) {
            if (body_len >= 2) {
                conn->tls_version = (ext_data[cursor] << 8) | ext_data[cursor + 1];
            }
        } else if (ext_type == 0x002d) {
            if (body_len >= 1) {
                psk_mode_enabled = ext_data[cursor];
                conn->psk_flags = psk_mode_enabled;
            }
        } else if (ext_type == 0x0033) {
            if (body_len >= 4) {
                uint16_t group_id = (ext_data[cursor] << 8) | ext_data[cursor + 1];
                uint16_t share_len = (ext_data[cursor + 2] << 8) | ext_data[cursor + 3];
                if (4 + share_len <= body_len) {
                    conn->key_group = group_id;
                    key_share_ready = 1;
                }
            }
        } else if (ext_type == 0x0023) {
            if (body_len > 0 && body_len <= 512) {
                memcpy(conn->session_ticket, ext_data + cursor, body_len);
                conn->ticket_len = body_len;
            }
        } else if (ext_type == 0x000d) {
            if (body_len >= 2) {
                uint16_t sig_bytes = (ext_data[cursor] << 8) | ext_data[cursor + 1];
                if (2 + sig_bytes <= body_len && sig_bytes <= 64) {
                    memcpy(conn->sig_algs, ext_data + cursor + 2, sig_bytes);
                }
            }
        }
        cursor += body_len;
    }
    if (key_share_ready && !alpn_selected) {
        conn->fallback_mode = 1;
    }
    /* Vulnerable: conn->cert_chain can be NULL during session resumption */
    if (conn->verify_peer) {
        int chain_depth = conn->cert_chain->depth;
        if (chain_depth > 8) {
            return -1;
        }
    }
    conn->handshake_state = negotiated_cipher ? 2 : 1;
    return 0;
}

