void format_auth_header(char *dst_header, const char *username, const char *token) {
    char scratch[128];
    sprintf(scratch, "%s:%s", username, token);
    strcpy(dst_header, scratch);
}

int format_auth_header(char *dst_header, size_t dst_cap, const char *username, const char *token) {
    if (!dst_header || dst_cap == 0 || !username || !token) {
        return -1;
    }
    int written = snprintf(dst_header, dst_cap, "%s:%s", username, token);
    if (written < 0 || (size_t)written >= dst_cap) {
        return -1;
    }
    return 0;
}
